-- Imaging clock placement, step 1 of 2: categories and projection map.
-- GENERATED by thebolt/proposals/2026-10-29-gen-imaging-migration.mjs. Do not hand-edit.
--
-- Adds the 9 imaging categories for the 10K renders and maps them, plus Positioning (52)
-- into Liners and New Music Front (55) into New-Music Sweepers. Touches no clock, so
-- nothing on air changes until step 2. Idempotent.
--
-- After it, on an imported station: Music > Inbox > Accept RadioDJ's filing, then apply
-- the staged changes in Music > Changes, so the new categories have songs before any
-- clock calls them. Step 2 refuses to run until they do.

BEGIN;

INSERT INTO categories (station_id, name, kind, default_target_turnover_hours) VALUES
  ('6a42a599-acfc-404f-a524-9fb9b65d36f3', 'Front-sell', 'imaging', NULL),
  ('6a42a599-acfc-404f-a524-9fb9b65d36f3', 'Back-sell', 'imaging', NULL),
  ('6a42a599-acfc-404f-a524-9fb9b65d36f3', 'New Music Back', 'imaging', NULL),
  ('6a42a599-acfc-404f-a524-9fb9b65d36f3', 'Power', 'imaging', NULL),
  ('6a42a599-acfc-404f-a524-9fb9b65d36f3', 'Discovery Sweepers', 'imaging', NULL),
  ('6a42a599-acfc-404f-a524-9fb9b65d36f3', 'Recurrent Sweepers', 'imaging', NULL),
  ('6a42a599-acfc-404f-a524-9fb9b65d36f3', 'Gold 90s', 'imaging', NULL),
  ('6a42a599-acfc-404f-a524-9fb9b65d36f3', 'Gold 00s', 'imaging', NULL),
  ('6a42a599-acfc-404f-a524-9fb9b65d36f3', 'Gold 10s', 'imaging', NULL)
ON CONFLICT ON CONSTRAINT categories_station_name_unique DO UPDATE SET kind = EXCLUDED.kind;

UPDATE categories SET rdj_subcategory_ids = ARRAY[37,52]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Liners';
UPDATE categories SET rdj_subcategory_ids = ARRAY[38,55]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'New-Music Sweepers';
UPDATE categories SET rdj_subcategory_ids = ARRAY[53]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Front-sell';
UPDATE categories SET rdj_subcategory_ids = ARRAY[54]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Back-sell';
UPDATE categories SET rdj_subcategory_ids = ARRAY[56]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'New Music Back';
UPDATE categories SET rdj_subcategory_ids = ARRAY[59]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Power';
UPDATE categories SET rdj_subcategory_ids = ARRAY[60]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Discovery Sweepers';
UPDATE categories SET rdj_subcategory_ids = ARRAY[61]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Recurrent Sweepers';
UPDATE categories SET rdj_subcategory_ids = ARRAY[62]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Gold 90s';
UPDATE categories SET rdj_subcategory_ids = ARRAY[63]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Gold 00s';
UPDATE categories SET rdj_subcategory_ids = ARRAY[64]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Gold 10s';

-- Derived membership, only for a station not yet imported (as the seed does). After the
-- import, membership is authored in Rotavox, so this inserts nothing.
INSERT INTO song_categories (song_id, category_id)
SELECT s.id, c.id FROM songs s JOIN categories c ON c.station_id = s.station_id
WHERE s.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND (SELECT membership_imported_at FROM stations WHERE id = '6a42a599-acfc-404f-a524-9fb9b65d36f3') IS NULL AND (
  (c.name = 'Liners' AND s.rdj_subcategory_id IN (37,52)) OR
  (c.name = 'New-Music Sweepers' AND s.rdj_subcategory_id IN (38,55)) OR
  (c.name = 'Front-sell' AND s.rdj_subcategory_id IN (53)) OR
  (c.name = 'Back-sell' AND s.rdj_subcategory_id IN (54)) OR
  (c.name = 'New Music Back' AND s.rdj_subcategory_id IN (56)) OR
  (c.name = 'Power' AND s.rdj_subcategory_id IN (59)) OR
  (c.name = 'Discovery Sweepers' AND s.rdj_subcategory_id IN (60)) OR
  (c.name = 'Recurrent Sweepers' AND s.rdj_subcategory_id IN (61)) OR
  (c.name = 'Gold 90s' AND s.rdj_subcategory_id IN (62)) OR
  (c.name = 'Gold 00s' AND s.rdj_subcategory_id IN (63)) OR
  (c.name = 'Gold 10s' AND s.rdj_subcategory_id IN (64))
)
ON CONFLICT ON CONSTRAINT song_categories_song_category_unique DO NOTHING;

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM categories WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name IN ('Liners', 'New-Music Sweepers', 'Front-sell', 'Back-sell', 'New Music Back', 'Power', 'Discovery Sweepers', 'Recurrent Sweepers', 'Gold 90s', 'Gold 00s', 'Gold 10s');
  IF n <> 11 THEN RAISE EXCEPTION 'expected 11 mapped imaging categories, got %', n; END IF;
END $$;

COMMIT;
